arguments.command:
cat > /app/work/trace.py << 'EOF'
import re, json
from collections import Counter

lines = open('/app/dataset/genealogy_trees.txt', encoding='utf-8').read().split('\n')
grid = lines[5:110]
W = max(len(r) for r in grid)
grid = [list(r.ljust(W)) for r in grid]
H = len(grid)

LET = 'A-Za-zĄąĆćĘęŁłŃńÓóŚśŹźŻż'
token_pat = re.compile(f'[{LET}]+(?: [{LET}]+)*')
raw = [''.join(r) for r in grid]
tokens = []
for r, row in enumerate(raw):
    for m in token_pat.finditer(row):
        t = m.group()
        if t == 'x':  # noise connector char
            continue
        tokens.append([r, m.start(), m.end(), t])
tokens.sort()
used = [False]*len(tokens)
groups = []
for i, t in enumerate(tokens):
    if used[i]: continue
    grp = [t]; used[i] = True; frontier = t
    for j in range(i+1, len(tokens)):
        if used[j]: continue
        u = tokens[j]
        if u[0] == frontier[0]+1 and not (u[2] < frontier[1]-1 or u[1] > frontier[2]+1):
            grp.append(u); used[j] = True; frontier = u
        elif u[0] > frontier[0]+1:
            break
    groups.append(grp)

HORIZ = set('-~+x')
VERT = set('|│/\\_.+x')

def is_borderish(r, c0, c1):
    if r < 0 or r >= H: return False
    seg = raw[r][max(0,c0):c1]
    return sum(ch in HORIZ for ch in seg) >= 2

boxes = []
for grp in groups:
    rtop = grp[0][0]; rbot = grp[-1][0]
    c0 = min(g[1] for g in grp); c1 = max(g[2] for g in grp)
    name = ' '.join(g[3] for g in grp)
    left = c0 - 2
    right = None
    for g in grp:
        row = raw[g[0]]
        for c in range(g[2], min(W, g[2]+25)):
            ch = row[c]
            if ch in '|│':
                right = c if right is None else max(right, c); break
            if ch != ' ': break
    if right is None: right = c1 + 2
    top = None
    for r in range(rtop-1, max(-1, rtop-4), -1):
        if is_borderish(r, left, right+1):
            top = r; break
    if top is None: top = rtop - 1
    bot = None
    for r in range(rbot+1, min(H, rbot+4)):
        if is_borderish(r, left, right+1):
            bot = r; break
    if bot is None: bot = rbot + 1
    boxes.append(dict(name=name, top=top, bot=bot, left=left, right=right))

# mask out box rectangles so connector tracing sees only lines
mask = [row[:] for row in grid]
for b in boxes:
    for r in range(b['top'], b['bot']+1):
        for c in range(max(0,b['left']-1), min(W, b['right']+2)):
            mask[r][c] = ' '
mraw = [''.join(r) for r in mask]

def rail_score(r, c):
    """count horizontal chars within +-6 cols on row r"""
    if r < 0 or r >= H: return 0
    seg = mraw[r][max(0,c-6):c+7]
    return sum(ch in HORIZ for ch in seg)

def find_vert(r, c, spread=2):
    """find vertical char at row r near col c"""
    if r < 0 or r >= H: return None
    for d in [0,-1,1,-2,2][:1+2*spread]:
        cc = c+d
        if 0 <= cc < W and mask[r][cc] in VERT:
            return cc
    return None

def trace(r, c, dr):
    """follow vertical path from (r,c) in direction dr; return list of (row,col) visited"""
    path = [(r,c)]
    while True:
        nxt = find_vert(r+dr, c)
        if nxt is None:
            nxt = find_vert(r+2*dr, c)  # gap of one row
            if nxt is None:
                break
            r, c = r+2*dr, nxt
        else:
            r, c = r+dr, nxt
        path.append((r,c))
    return path

def find_rail(path, dr):
    """given trace path, find the first rail row encountered (scanning along path);
       also allow rail to be 1-2 rows beyond the end of the path"""
    for (r,c) in path[1:]:
        if rail_score(r,c) >= 3:
            return (r,c)
    er, ec = path[-1]
    for k in (1,2):
        if rail_score(er+dr*k, ec) >= 3:
            return (er+dr*k, ec)
    return None

results = []
for i, b in enumerate(boxes):
    # entry above top
    entry_rail = None
    cands = []
    for rr in (b['top']-1, b['top']-2):
        if rr < 0: continue
        for c in range(max(0,b['left']-1), min(W, b['right']+2)):
            if mask[rr][c] in VERT:
                cands.append((rr,c))
        if cands: break
    for (rr,cc) in cands:
        p = trace(rr, cc, -1)
        rl = find_rail(p, -1)
        if rl:
            entry_rail = rl; break
    # exit below bottom
    exit_rail = None
    ecands = []
    for rr in (b['bot']+1, b['bot']+2):
        if rr >= H: continue
        for c in range(max(0,b['left']-1), min(W, b['right']+2)):
            if mask[rr][c] in VERT:
                ecands.append((rr,c))
        if ecands: break
    for (rr,cc) in ecands:
        p = trace(rr, cc, +1)
        rl = find_rail(p, +1)
        if rl:
            exit_rail = rl; break
    results.append(dict(idx=i, name=b['name'], entry=entry_rail, exit=exit_rail,
                        n_entry_cands=len(cands)))

no_entry = [r for r in results if r['entry'] is None]
print("boxes:", len(boxes))
print("boxes with no entry rail (root candidates):", [(r['idx'], r['name']) for r in no_entry])
print("boxes with exit rail:", sum(1 for r in results if r['exit']))
json.dump(dict(boxes=boxes, results=results), open('/app/work/trace1.json','w'), ensure_ascii=False)
